"""Build the fixed saved-terminal layered replay notebook; never execute it."""
from pathlib import Path
import argparse,ast,json,re
ROOT=Path(__file__).resolve().parents[1]
OUTPUT=ROOT/'notebooks/zero_mean_c1_layered_transport_v1_colab.ipynb'
MARKDOWN='# Zero-mean C1 matched five-layer transfer diagnostic\n\nRun all reuses the three saved terminals from run20260930T113335113338Z/source05beeaa. It performs no new generation or Transformer calls. Per arm, one FP32 VAE decode gives a saved clamped float buffer; its saved original uint8 raster supplies a matched first MP4, whose actual readback supplies a matched second MP4. The five primary layers are terminal, float re-encode, RGB8 re-encode, matched SOURCE MP4 re-encode, and matched FULL MP4 re-encode.\n\nAll encodes receive the complete181 frames. All normalized tensors retain46 latent steps; the unchanged zero-mean receiver scores regular1..44 at fixed phase0 using all174 valid paths,3915 catalog slots per condition. Fixed phase is a diagnostic support choice, not synchronization recovery. Thirty raw path/payload conditions are persisted before30 path truth joins and60 message comparisons. Existing R45 terminal results and historical FULL tensors/raw are separate references.\n\nPlanned calls:3 VAE decode,12 VAE encode,6 new MP4 saves,6 actual MP4 reads,0 Transformer. Save3 FP32 float and3 uint8 raster tensors (~1.24GiB raw total),12 new normalized tensors (~86MiB),6 new videos, complete costs/projections and preclamp statistics. The first float boundary combines decode, mapping, clamp and encode; it is not a pure encoder-loss measurement. New/old media hashes are compared but need not match across execution environments.\n\nFailures keep all fixed rows. Terminal and history remain independently usable if the VAE cannot load. Primary execution, historical reference and whole-package completeness are reported separately. All path scores remain uncalibrated and unaccepted; no automatic science, FPR, phase, editing or quality PASS. No new crop/four-phase matrix, no C2, no writer/reader changes. Local validation uses synthetic mock VAE/codec only, not real media.\n\nCurrent Python, a working Torch pair and fresh child processes are reused. No venv, exact-Python or GPU-model gate. Source is an unpublished draft until the main session publishes and binds its immutable SHA.\n'
SETUP="from pathlib import Path\nimport datetime,hashlib,json,os,subprocess,sys,traceback\nSTAMP=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')\nOUTPUT=Path('/content/drive/MyDrive/Video-WM/Zero-Mean-C1-Layered-Transport-V1')/STAMP\nOUTPUT.mkdir(parents=True,exist_ok=False)\nREPO=Path('/content/SC-SSTW-LAYERED-TRANSPORT-'+STAMP)\nRUN_OUTPUT=OUTPUT/'fixed_reference'\nPYTHON=sys.executable\nINPUT_ROOT=Path('/content/drive/MyDrive/Video-WM/Video-Overlap-Zero-Mean-C1-V1/20260930T113335113338Z/fixed_reference')\nARMS=('OFF','PAYLOAD_MULTI','OVERLAP_MULTI');KEYS=('CORRECT','WRONG')\nLAYERS=('TERMINAL_PREFIX44','FLOAT_CLAMPED','RGB8_NO_CODEC','MATCHED_SOURCE_MP4','MATCHED_FULL_RESAVED')\nFIXED={'arms': 3, 'layers': 5, 'normalized_records': 15, 'path_reads': 30, 'payload_reads': 30, 'path_posthoc': 30, 'message_evaluations': 60, 'catalog_slots': 117450, 'valid_costs': 5220, 'structural_exclusions': 112230, 'candidates_per_condition': 3915, 'valid_per_condition': 174, 'decode_diagnostics': 3, 'historical_normalized_references': 3, 'historical_raw_references': 6, 'historical_media_hash_comparisons': 6}\nsetup=dict(status='SETUP_STARTED',source_sha=SOURCE_SHA,fixed_denominator=FIXED,input_root=str(INPUT_ROOT),\n normalized={a+'/'+l:{'status':'NOT_RUN_SETUP'} for a in ARMS for l in LAYERS},\n reads={a+'/'+l+'/'+k:{'status':'NOT_RUN_SETUP','catalog_slots':3915,'valid_slots':174,'excluded_slots':3741} for a in ARMS for l in LAYERS for k in KEYS},\n path_posthoc={a+'/'+l+'/'+k:{'status':'NOT_RUN_SETUP'} for a in ARMS for l in LAYERS for k in KEYS},\n message_evaluations={a+'/'+l+'/'+k+'/'+t:{'status':'NOT_RUN_SETUP'} for a in ARMS for l in LAYERS for k in KEYS for t in ('REGISTERED','WRONG_MESSAGE')},\n rasters={a+'/'+l:{'status':'NOT_RUN_SETUP'} for a in ARMS for l in LAYERS[1:3]},\n media={a+'/'+l:{'status':'NOT_RUN_SETUP'} for a in ARMS for l in LAYERS[3:]},\n decode_diagnostics={a:{'status':'NOT_RUN_SETUP'} for a in ARMS},\n planned_calls=dict(transformer=0,vae_decode=3,vae_encode=12,new_mp4_save=6,new_mp4_read=6,new_path_infer=30,new_payload_read=30))\ndef write_json(path,value):\n    temp=path.with_suffix(path.suffix+'.tmp');temp.write_text(json.dumps(value,indent=2)+'\\n');os.replace(temp,path)\ndef failed(stage,exc):\n    setup.update(status='SETUP_FAILED',stage=stage,error=f'{type(exc).__name__}: {exc}')\n    write_json(OUTPUT/'setup_receipt.json',setup)\n    write_json(OUTPUT/'setup_failure.json',dict(stage=stage,error=str(exc),traceback=traceback.format_exc()))\ndef logged(command,stage,cwd=None,check=True):\n    try:\n        with (OUTPUT/'execution.log').open('a') as log:\n            log.write('COMMAND '+repr(command)+'\\n');log.flush()\n            child=subprocess.Popen(command,cwd=cwd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1)\n            for line in child.stdout:print(line,end='',flush=True);log.write(line);log.flush()\n            code=child.wait();log.write('EXIT '+str(code)+'\\n')\n        if check and code:raise subprocess.CalledProcessError(code,command)\n        return code\n    except Exception as exc:failed(stage,exc);raise\nwrite_json(OUTPUT/'setup_receipt.json',setup)\nprint('Fixed input:',INPUT_ROOT,'New output:',OUTPUT)\nif SOURCE_SHA is None:\n    error=RuntimeError('Unpublished draft: bind verified published source SHA before Run all')\n    failed('SOURCE_BINDING',error);raise error\n"
ENVIRONMENT="try:\n    logged(['git','clone','--filter=blob:none','https://github.com/RICHAAARC/SC-SSTW.git',str(REPO)],'SOURCE_CLONE')\n    logged(['git','-C',str(REPO),'fetch','origin',SOURCE_SHA],'SOURCE_FETCH')\n    logged(['git','-C',str(REPO),'checkout','--detach',SOURCE_SHA],'SOURCE_CHECKOUT')\n    actual=subprocess.check_output(['git','-C',str(REPO),'rev-parse','HEAD'],text=True).strip()\n    dirty=subprocess.check_output(['git','-C',str(REPO),'status','--porcelain'],text=True)\n    if actual!=SOURCE_SHA or dirty:raise RuntimeError('source SHA/clean checkout mismatch')\n    write_json(OUTPUT/'source_receipt.json',dict(source_sha=actual,clean=True))\n    torch_ok=logged([PYTHON,'-c','import torch,torchvision; print(torch.__version__,torchvision.__version__)'],'TORCH_PROBE',check=False)==0\n    if not torch_ok:\n        logged([PYTHON,'-m','pip','install','--upgrade','torch','torchvision'],'TORCH_REPAIR')\n    logged([PYTHON,'-m','pip','install','-r',str(REPO/'experiments/wan_state_clock/requirements-grow-video-reference.txt')],'DEPENDENCIES')\n    dependency_code=logged([PYTHON,'-m','pip','check'],'DEPENDENCY_REPORT',check=False)\n    setup['dependency_check_returncode']=dependency_code\n    if dependency_code:print('Metadata conflicts retained; actual imports determine availability.')\n    (OUTPUT/'environment_freeze.txt').write_text(subprocess.check_output([PYTHON,'-m','pip','freeze'],text=True))\n    import_code='import json,torch; from diffusers import AutoencoderKLWan; from experiments.wan_state_clock.zero_mean_c1_layered_transport_run import environment; r=environment(); r.update(cuda_available=torch.cuda.is_available()); print(json.dumps(r))'\n    env=json.loads(subprocess.check_output([PYTHON,'-c',import_code],cwd=REPO,text=True))\n    write_json(OUTPUT/'environment_receipt.json',env)\n    if not env['cuda_available']:print('CUDA unavailable: CPU path selected; much slower.')\n    logged(['ffmpeg','-version'],'FFMPEG_PROBE');logged(['ffprobe','-version'],'FFPROBE_PROBE')\n    setup.update(status='SETUP_COMPLETE',python_executable=PYTHON,environment_strategy='current_python_fresh_children')\n    write_json(OUTPUT/'setup_receipt.json',setup)\nexcept Exception as exc:failed('SOURCE_OR_ENVIRONMENT',exc);raise\n"
RUN="try:\n    from google.colab import userdata\n    token=userdata.get('HF_TOKEN')\n    if token:os.environ['HF_TOKEN']=token\nexcept Exception:\n    pass\nfinally:\n    token=None\ncommand=[PYTHON,'-u','-m','experiments.wan_state_clock.zero_mean_c1_layered_transport_run','--output',str(RUN_OUTPUT),'--input-root',str(INPUT_ROOT)]\ntry:\n    returncode=logged(command,'FIXED_RUN',cwd=REPO,check=False)\n    RESULT_PATH=RUN_OUTPUT/'result.json'\n    write_json(OUTPUT/'execution_receipt.json',dict(command=command,returncode=returncode,result_path=str(RESULT_PATH),result_exists=RESULT_PATH.is_file()))\n    if not RESULT_PATH.is_file():raise RuntimeError('No runner result; full setup denominator is retained')\n    setup.update(status='SUPERSEDED_BY_RESULT',result_path=str(RESULT_PATH));write_json(OUTPUT/'setup_receipt.json',setup)\nexcept Exception as exc:failed('RUNNER',exc);raise\n"
DISPLAY="result=json.loads(RESULT_PATH.read_text())\nif result['source_sha']!=SOURCE_SHA or result['fixed_denominator']!=FIXED:raise RuntimeError('result identity/denominator mismatch')\nprint('Primary:',result['primary_status'],result['counts'])\nprint('Historical references:',result['historical_reference_status'],'Whole package:',result['package_status'])\nprint('Calls:',result['calls'],'VAE loaded:',result['model_loaded'])\nprint('Preclamp:',result['decode_diagnostics'])\nfor name,row in result['path_posthoc'].items():\n    print(name,row['status'],'truth in top=',row.get('truth_in_top'),'canonical=',row.get('canonical_catalog_index'),'true-minus-winner=',row.get('true_minus_winner'))\nfor name,row in result['message_evaluations'].items():\n    print(name,row['status'],'diagnostic bit errors=',row.get('diagnostic_bit_errors'))\nprint('All scores remain uncalibrated. Fixed g0 is not recovered phase; historical byte equality is not required.')\nprint('Historical comparisons:',result['historical_comparisons'])\nprint('Evidence ceiling:',result['evidence_ceiling'])\nfrom IPython.display import Video,display\nfor name,row in result['media'].items():\n    print(name,row['status'])\n    if row['status']=='SAVED' and Path(row['path']).is_file():\n        try:display(Video(str(row['path']),embed=True))\n        except Exception as exc:print('Preview unavailable; saved MP4 remains at',row['path'],type(exc).__name__,str(exc))\nprint('Inspect visible quality separately; no quality threshold or quality PASS.')\n"

def build(source_sha=None,output=OUTPUT):
    if source_sha is not None and not re.fullmatch('[0-9a-f]{40}',source_sha):raise ValueError('published immutable source SHA required')
    wording=('Published source: '+source_sha+'. Checks out this immutable source.' if source_sha else 'UNPUBLISHED DRAFT: publish and verify source before binding.')
    sources=[('code',"from google.colab import drive\ndrive.mount('/content/drive')\n"),
      ('markdown',MARKDOWN.replace('Source is an unpublished draft until the main session publishes and binds its immutable SHA.',wording)),
      ('code',f'SOURCE_SHA = {source_sha!r}\n'+SETUP),('code',ENVIRONMENT),('code',RUN),('code',DISPLAY)]
    cells=[]
    for i,(kind,text) in enumerate(sources):
        cell=dict(cell_type=kind,id=f'layered-transport-{i}',metadata={},source=text.splitlines(keepends=True))
        if kind=='code':ast.parse(text);cell.update(outputs=[],execution_count=None)
        cells.append(cell)
    result=dict(nbformat=4,nbformat_minor=5,cells=cells,metadata=dict(kernelspec=dict(display_name='Python3',language='python',name='python3'),
      language_info=dict(name='python'),candidate_binding=dict(source_sha=source_sha,status='PUBLISHED_SHA_BOUND' if source_sha else 'UNPUBLISHED_DRAFT',
      execution='User-run only; no local real VAE/codec/model execution')))
    Path(output).write_text(json.dumps(result,indent=1)+'\n');return Path(output)

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--source-sha');parser.add_argument('--output',type=Path,default=OUTPUT)
    args=parser.parse_args();print(build(args.source_sha,args.output))
